return [{
  json: {
    study_id: 'study_test_05',
    building_id: 'bldg_001',
    zone_ids: ['north_entrance_lobby'],
    behavior_targets: [
      { behavior_name: 'entry_surge' },
      { behavior_name: 'door_hesitation' },
      { behavior_name: 'queue_formation' },
      { behavior_name: 'directional_flow_imbalance' }
    ],
    setup_instructions: 'Monitor the main turnstile zone for occupant flow behaviors. Flag any clustering near the entry point or hesitation at the door.',
    last_modified_seen: null,
    debug_mode: true,
  }
}];

// Safely read the triggering input — works whether fired from
// orchestrator, manual test trigger, or loop re-entry
let orchestratorInput = {};
try { orchestratorInput = $('When Executed by Orchestrator').item.json; } catch {}
if (!orchestratorInput.study_id) {
  try { orchestratorInput = $('Inject Test Payload').item.json; } catch {}
}

const studyRows = Array.isArray($input.first().json) ? $input.first().json : [$input.first().json];
const study = studyRows[0] ?? {};

const startedAt = study.started_at ? new Date(study.started_at) : new Date();
const durationSeconds = study.duration_seconds ?? orchestratorInput.duration_seconds ?? 600;
const studyEndTime = new Date(startedAt.getTime() + durationSeconds * 1000);

return [{
  json: {
    study_id: study.study_id ?? orchestratorInput.study_id,
    building_id: study.building_id ?? orchestratorInput.building_id ?? null,
    zone_ids: orchestratorInput.zone_ids ?? [],
    behavior_targets: orchestratorInput.behavior_targets ?? [],
    setup_instructions: orchestratorInput.setup_instructions ?? study.study_goal ?? '',
    snapshot_url: $env.HA_SNAPSHOT_FOLDER_URL || 'http://192.168.204.6:8123/local/snapshots/snapshot_1.jpg',
    study_end_time: studyEndTime.toISOString(),
    last_modified_seen: orchestratorInput.last_modified_seen ?? null,
    debug_mode: orchestratorInput.debug_mode ?? false,
  }
}];

const ctx = $('Prepare Monitoring Context').item.json;
const headers = $json.headers ?? $json;

const lastModified = headers['last-modified'] ?? headers['Last-Modified'] ?? null;
const contentLength = headers['content-length'] ?? headers['Content-Length'] ?? null;
const changeSignal = lastModified ?? contentLength ?? null;
const lastSeen = ctx.last_modified_seen ?? null;
const imageChanged = changeSignal !== null && changeSignal !== lastSeen;

const now = new Date();
const studyEndTime = new Date(ctx.study_end_time);
const studyExpired = now >= studyEndTime;

return [{
  json: {
    ...ctx,
    last_modified_current: changeSignal,
    image_changed: imageChanged,
    study_expired: studyExpired,
    checked_at: now.toISOString(),
  }
}];

const ctx = $json;
return [{
  json: {
    monitoring_status: { status: 'study_complete', study_id: ctx.study_id, completed_at: new Date().toISOString(), study_end_time: ctx.study_end_time },
    study_dataset_reference: { table: 'BE_behavior_detections', study_id: ctx.study_id },
    next_action: 'call_insights_agent',
  }
}];

const ctx = $('Check If Image Changed').item.json;
const binaryKey = Object.keys($binary ?? {})[0] ?? 'data';
const binaryData = $binary?.[binaryKey];
let base64Image = null;
let mimeType = 'image/jpeg';
if (binaryData) {
  base64Image = binaryData.data ?? null;
  mimeType = binaryData.mimeType ?? 'image/jpeg';
}
return [{
  json: {
    ...ctx,
    image_base64: base64Image,
    image_mime_type: mimeType,
    image_data_url: base64Image ? `data:${mimeType};base64,${base64Image}` : null,
    image_id: 'snapshot_' + new Date().toISOString().replace(/[:.]/g, '-'),
    timestamp: new Date().toISOString(),
    zone_id: ctx.zone_ids?.[0] ?? null,
  }
}];

