={{ JSON.stringify({
  model: $env.VISION_MODEL || 'gpt-4.1-mini',
  input: [
    { role: 'system', content: [{ type: 'input_text', text: 'You are the only image-analysis agent in a building behavior monitoring system. Analyze the image for the requested occupant behaviors only. Return valid JSON only with these exact keys: detected_behaviors (array of objects with name and present fields), confidence_scores (object mapping behavior name to 0-1 score), occupant_count (integer or null), notes (string). Never include recommendations or conclusions.' }] },
    { role: 'user', content: [
      { type: 'input_text', text: 'Study ID: ' + $json.study_id + '\nZone: ' + ($json.zone_id || 'unknown') + '\nBehavior targets: ' + JSON.stringify($json.behavior_targets) + '\nInstructions: ' + ($json.setup_instructions || '') },
      { type: 'input_image', image_url: $json.image_data_url, detail: 'auto' }
    ]}
  ],
  max_output_tokens: 1000
}) }}

