const ctx = $('Encode Image to Base64').item.json;
const rawText = $json.output?.[0]?.content?.[0]?.text ?? $json.output_text ?? '';
let parsed = {};
let parseError = null;
try {
  const clean = rawText.replace(/```json|^```|```$/gm, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  parseError = 'vision_json_parse_failed';
}
return [{
  json: {
    study_id: ctx.study_id,
    image_id: ctx.image_id,
    timestamp: ctx.timestamp,
    zone_id: ctx.zone_id,
    detected_behaviors: parsed.detected_behaviors ?? [],
    confidence_scores: parsed.confidence_scores ?? {},
    occupant_count: parsed.occupant_count ?? null,
    notes: parsed.notes ?? (parseError ? 'Parse failed: ' + rawText.slice(0, 200) : ''),
    model_version: $env.VISION_MODEL || 'gpt-4.1-mini',
    parse_error: parseError,
    snapshot_url: ctx.snapshot_url,
    study_end_time: ctx.study_end_time,
    behavior_targets: ctx.behavior_targets,
    setup_instructions: ctx.setup_instructions,
    zone_ids: ctx.zone_ids,
    building_id: ctx.building_id,
    last_modified_current: ctx.last_modified_current,
    debug_mode: ctx.debug_mode,
  }
}];

let ctx = {};
try { ctx = $('Parse Detection JSON').item.json; } catch {}
if (!ctx.study_id) { try { ctx = $('Check If Image Changed').item.json; } catch {} }
return [{
  json: {
    study_id: ctx.study_id,
    building_id: ctx.building_id ?? null,
    zone_ids: ctx.zone_ids ?? [],
    behavior_targets: ctx.behavior_targets ?? [],
    setup_instructions: ctx.setup_instructions ?? '',
    snapshot_url: ctx.snapshot_url,
    study_end_time: ctx.study_end_time,
    last_modified_seen: ctx.last_modified_current ?? ctx.last_modified_seen ?? null,
    debug_mode: ctx.debug_mode ?? false,
  }
}];
